INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Command-Pattern nur für Undo-Funktionen nützlich?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Befehlssteuerung generell"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Command-Pattern?', 3, '[{"text": "Flexible Befehlsverarbeitung", "correct": true, "because": "Trennt Aufruf von Ausführung"}, {"text": "Datenmodellierung", "correct": false, "because": "Kein Datenfokus"}, {"text": "UI-Gestaltung", "correct": false, "because": "Kein Designaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Command-Pattern?', 5, '[{"text": "Command", "correct": true, "because": "Definiert Befehl"}, {"text": "Receiver", "correct": true, "because": "Führt Befehl aus"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Hardwareknoten", "correct": false, "because": "Kein Pattern-Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Command-Pattern trennt Aufrufer und Aktion. b) Es ersetzt Strategy-Pattern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Strategy für Algorithmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Command-Pattern?', 4, '[{"text": "Befehlsobjekte", "correct": false, "because": "Kern des Patterns"}, {"text": "Invoker", "correct": false, "because": "Startet Befehle"}, {"text": "UI-Optik", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Command-Pattern auch ohne Receiver funktioniert?', 2, '[{"text": "Nein", "correct": true, "because": "Receiver führt Aktion aus"}, {"text": "Ja", "correct": false, "because": "Receiver essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Invoker im Command-Pattern?', 3, '[{"text": "Befehlsauslöser", "correct": true, "because": "Startet Command-Ausführung"}, {"text": "Datenquelle", "correct": false, "because": "Receiver verarbeitet"}, {"text": "UI-Steuerung", "correct": false, "because": "Nicht UI-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zum Command-Pattern?', 5, '[{"text": "Invoker", "correct": true, "because": "Löst Befehle aus"}, {"text": "ConcreteCommand", "correct": true, "because": "Implementiert Befehle"}, {"text": "Datenfluss", "correct": false, "because": "Kein Pattern-Teil"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Command-Pattern ermöglicht Undo. b) Es ändert die Receiver-Logik. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Receiver bleibt unverändert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das Command-Pattern?', 4, '[{"text": "Command-Interface", "correct": false, "because": "Definiert Befehle"}, {"text": "Receiver", "correct": false, "because": "Führt Aktion aus"}, {"text": "3D-Grafiken", "correct": true, "because": "Kein Pattern-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Command-Pattern nur für Undo?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Queuing, Logging"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Command-Pattern?', 4, '[{"text": "Rückgängigmachen", "correct": true, "because": "Undo-Funktion möglich"}, {"text": "Befehlssteuerung", "correct": true, "because": "Flexibel ausführbar"}, {"text": "Datenfluss", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Command-Pattern die Ausführung verzögert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Verzögerung optional"}, {"text": "Ja", "correct": false, "because": "Abhängig von Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Command-Pattern?', 3, '[{"text": "Flexibilität", "correct": true, "because": "Befehle austauschbar"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Flexibilität zählt mehr"}, {"text": "UI-Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Command-Pattern trennt Aufruf und Aktion. b) Es erstellt neue Receiver.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Receiver bleibt bestehen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen nutzen das Command-Pattern?', 5, '[{"text": "Undo/Redo", "correct": true, "because": "Befehle rückgängig machbar"}, {"text": "Task-Queuing", "correct": true, "because": "Befehle aufschiebbar"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "UI-Animation", "correct": false, "because": "Kein UI-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Command-Pattern unwichtig?', 3, '[{"text": "Befehlsausführung", "correct": false, "because": "Kern des Patterns"}, {"text": "Invoker", "correct": false, "because": "Startet Befehle"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann das Command-Pattern mehrere Befehle bündeln?', 3, '[{"text": "Ja", "correct": true, "because": "Macro-Commands möglich"}, {"text": "Nein", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Command-Pattern für einfache Aktionen übertrieben ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch einfach nutzbar"}, {"text": "Ja", "correct": false, "because": "Skalierung unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für den Befehl im Command-Pattern?', 4, '[{"text": "Command-Objekt", "correct": true, "because": "Kapselt Befehlslogik"}, {"text": "Datenfluss", "correct": false, "because": "Kein Pattern-Teil"}, {"text": "UI-Komponente", "correct": false, "because": "Nicht UI-spezifisch"}]');
